function generateEnvMap(renderer){const size=128;const cubeRenderTarget=new THREE.WebGLCubeRenderTarget(size);const cubeCamera=new THREE.CubeCamera(0.1,100,cubeRenderTarget);const envScene=new THREE.Scene;const topPlane=new THREE.Mesh(new THREE.PlaneGeometry(20,20),new THREE.MeshBasicMaterial({color:657930,side:THREE.DoubleSide}));topPlane.position.y=6;topPlane.rotation.x=Math.PI/2;envScene.add(topPlane);[[-2,5,-2],[2,5,-2],[0,5,0]].forEach((p)=>{const spot=new THREE.Mesh(new THREE.CircleGeometry(1.2,16),new THREE.MeshBasicMaterial({color:1118481,side:THREE.DoubleSide}));spot.position.set(p[0],p[1],p[2]);spot.rotation.x=Math.PI/2;envScene.add(spot)});const floorEnv=new THREE.Mesh(new THREE.PlaneGeometry(20,20),new THREE.MeshBasicMaterial({color:131586,side:THREE.DoubleSide}));floorEnv.position.y=-2;floorEnv.rotation.x=Math.PI/2;envScene.add(floorEnv);const neonLine=new THREE.Mesh(new THREE.BoxGeometry(8,0.1,0.1),new THREE.MeshBasicMaterial({color:1710618}));neonLine.position.set(0,-0.5,-2);envScene.add(neonLine);const backEnv=new THREE.Mesh(new THREE.PlaneGeometry(14,8),new THREE.MeshBasicMaterial({color:526344}));backEnv.position.set(0,2,-5);envScene.add(backEnv);const sideL=new THREE.Mesh(new THREE.PlaneGeometry(10,8),new THREE.MeshBasicMaterial({color:657930}));sideL.position.set(-8,2,0);sideL.rotation.y=Math.PI/2;envScene.add(sideL);const sideR=new THREE.Mesh(new THREE.PlaneGeometry(10,8),new THREE.MeshBasicMaterial({color:657930}));sideR.position.set(8,2,0);sideR.rotation.y=-Math.PI/2;envScene.add(sideR);[[-3,3,-4.5],[0,3,-4.5],[3,3,-4.5]].forEach((p)=>{const hl=new THREE.Mesh(new THREE.SphereGeometry(0.3,8,8),new THREE.MeshBasicMaterial({color:2236962}));hl.position.set(p[0],p[1],p[2]);envScene.add(hl)});const overheadHl=new THREE.Mesh(new THREE.PlaneGeometry(6,3),new THREE.MeshBasicMaterial({color:1118481,side:THREE.DoubleSide}));overheadHl.position.set(0,5.5,-1);overheadHl.rotation.x=Math.PI/2;envScene.add(overheadHl);cubeCamera.position.set(0,0.5,-1.5);cubeCamera.update(renderer,envScene);return cubeRenderTarget.texture}